# per base edge: (A_e as 4 rows, b_e)
LETTERS = [([[2, 2, 0, 1], [2, 0, 1, 0], [1, 2, 1, 2], [1, 1, 1, 2]], (2, 1, 1, 2)), ([[2, 2, 1, 1], [2, 0, 0, 0], [1, 1, 0, 2], [2, 0, 0, 1]], (2, 0, 2, 2)), ([[0, 0, 1, 0], [2, 2, 2, 1], [1, 1, 1, 0], [0, 1, 0, 2]], (0, 2, 2, 1)), ([[2, 2, 1, 2], [2, 1, 1, 2], [0, 1, 1, 1], [2, 1, 1, 1]], (1, 2, 1, 2)), ([[2, 1, 0, 1], [2, 0, 1, 2], [0, 0, 0, 1], [1, 0, 0, 2]], (0, 2, 2, 0)), ([[1, 1, 1, 2], [1, 2, 1, 0], [2, 1, 0, 1], [0, 2, 0, 1]], (1, 0, 1, 0)), ([[1, 2, 1, 1], [1, 1, 1, 1], [2, 1, 0, 1], [2, 0, 0, 0]], (1, 1, 2, 0)), ([[2, 2, 1, 0], [2, 2, 2, 1], [1, 1, 1, 0], [2, 0, 1, 0]], (2, 2, 1, 0)), ([[1, 1, 2, 0], [1, 0, 0, 0], [1, 2, 0, 2], [1, 1, 2, 1]], (1, 1, 1, 1)), ([[2, 1, 2, 0], [0, 1, 1, 2], [1, 2, 1, 1], [0, 0, 1, 1]], (2, 2, 0, 0)), ([[1, 0, 1, 0], [1, 1, 1, 2], [2, 2, 2, 2], [1, 0, 0, 1]], (2, 2, 0, 0)), ([[2, 2, 1, 0], [0, 0, 2, 0], [0, 1, 1, 1], [1, 0, 1, 0]], (2, 2, 1, 0))]

def mat_vec(A, v):
    return tuple(sum(A[r][c] * v[c] for c in range(4)) % 3 for r in range(4))

def vid(v): return v[0] + 3 * v[1] + 9 * v[2] + 27 * v[3]

def build():
    nA = M * 81; E = []
    vecs = list(itertools.product(range(3), repeat=4))
    assert len(CTRL) == 4 * M
    for (a, b, e) in CTRL:
        A, bv = LETTERS[e]
        for x in vecs:
            y0 = mat_vec(A, x)
            for lam in range(3):
                y = tuple((p + lam * q) % 3 for p, q in zip(y0, bv))
                E.append((a * 81 + vid(x), nA + b * 81 + vid(y)))
    assert len(set(E)) == len(E), 'repeated edge'
    return 2 * nA, E

if __name__ == '__main__':
    n, E = build()
    with open(sys.argv[1], 'w') as f:
        f.write(f"{n}\n"); f.writelines(f"{u} {v}\n" for u, v in E)
    print('vertices', n, 'edges', len(E))
